command:
$ErrorActionPreference = 'Stop'
$branch = 'feat/issue608-slice6-native-review-assist-20261124'
$expected = 'f523e48cb4fb99e2dd6a755825c3bc064255c574'
& git fetch --no-tags origin ("refs/heads/" + $branch + ":refs/remotes/origin/" + $branch)
if ($LASTEXITCODE -ne 0) { throw 'Fetch of approved PR branch failed' }
$observed = (& git rev-parse ("refs/remotes/origin/" + $branch)).Trim()
if ($LASTEXITCODE -ne 0 -or $observed -ne $expected) { throw "PR head changed; expected $expected got $observed" }
& git checkout --detach $observed
if ($LASTEXITCODE -ne 0) { throw 'Detached checkout failed' }
$env:PYTHONDONTWRITEBYTECODE = '1'
foreach ($name in @('DCOIR_GEMINI_API','DCOIR_GITHUB_FG_TOKEN','DCOIR_GITHUB_CL_TOKEN','DCOIR_OPENAI_API_KEY','DCOIR_OPENAI_PROJECT_ID','OPENAI_API_KEY')) {
  Remove-Item ("Env:" + $name) -ErrorAction SilentlyContinue
}
$python = Get-Command python3 -ErrorAction SilentlyContinue
if (-not $python) { $python = Get-Command python -ErrorAction Stop }
$tests = @(
  'project_sources/collector/tools/test_run_powershell_review_assist_workflow_mode.py',
  'project_sources/collector/tools/test_run_powershell_review_assist_report.py',
  'project_sources/collector/tools/test_run_powershell_review_assist_safety.py',
  '.github/github_actions/tools/test_report_only_static_gate_actions.py'
)
foreach ($test in $tests) {
  Write-Host "=== Exact-head test: $test ==="
  & $python.Source $test -v
  if ($LASTEXITCODE -ne 0) { throw "Exact-head test failure ($LASTEXITCODE): $test" }
}
& $python.Source project_sources/collector/tools/run_powershell_review_assist_report.py --help
if ($LASTEXITCODE -ne 0) { throw 'CLI help failed' }
& git diff --check
if ($LASTEXITCODE -ne 0) { throw 'Git diff whitespace check failed' }
$dirty = @(& git status --porcelain)
if ($dirty.Count -gt 0) { throw "Validation modified repository files: $($dirty -join '; ')" }
Write-Host "Issue #608 Slice 6 read-only exact-head validation PASS at $expected."
